WITH with_gaps AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) + INTERVAL 60 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM payments), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT CASE WHEN amount >= 1410 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS span_minutes, COUNT(DISTINCT method) AS distinct_methods, SUM(is_new_burst) AS total_is_new_burst, AVG(amount) AS avg_amount, COUNT(*) AS row_count FROM sessionized GROUP BY 1;
